'use strict';
const $=id=>document.getElementById(id),colors=['#43e4af','#51cafa','#938cf9','#f4be63','#f47c88','#82adc6'];let filter='all',toastTimer;
const time=t=>new Date(t).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
let historyDate=null,requestSequence=0,fallbackTimer=null,followToday=true,liveViewRequested=false,selectDeviceView=()=>{};
function todayWib(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return p.year+'-'+p.month+'-'+p.day;}let summary24h=null;let floors=[],logs=[],serverNow=Date.now(),apiConnected=false;
function mean(nodes){const valid=nodes.filter(n=>Number.isFinite(n.latency));return valid.length?Math.round(valid.reduce((a,n)=>a+n.latency,0)/valid.length):null;}
function internetQuality(f){if(!selectedDevice&&f.nodes[0].summary_24h){const stats=Object.values(f.nodes[0].summary_24h.services).map(s=>s.total),total=stats.reduce((v,s)=>v+s.tests,0),failed=stats.reduce((v,s)=>v+s.failed,0),good=total-failed,rate=total?good/total*100:null,ms=good?Math.round(stats.reduce((v,s)=>v+(s.average_ms||0)*(s.tests-s.failed),0)/good):null,kind=!total?'unknown':!good?'down':rate<95?'partial':ms>800?'slow':'normal';return{kind,label:{unknown:'Belum diketahui',down:'Tidak terjangkau',partial:'Sebagian gagal',slow:'Lambat',normal:'Normal'}[kind],rate,ms,total,note:'Ringkasan pengujian 24 jam'};}const online=f.nodes.filter(n=>n.online),end=serverNow,tests=online.flatMap(n=>n.internet).filter(t=>t.time>=end-300000),ok=tests.filter(t=>t.ok);if(!tests.length)return{kind:'unknown',label:'Belum diketahui',rate:null,ms:null,total:0,note:online.length?'Belum ada hasil uji internet dalam 5 menit terakhir. Periksa URL probe internet HTTP di /setup Wemos; koneksi Wi-Fi saja belum membuktikan akses internet.':'Perangkat belum mengirim data atau offline; status internet belum dapat dinilai.'};const rate=ok.length/tests.length*100,ms=ok.length?Math.round(ok.reduce((a,t)=>a+t.ms,0)/ok.length):null;const kind=!ok.length?'down':rate<95?'partial':ms>800?'slow':'normal';return{kind,label:{down:'Tidak terjangkau',partial:'Akses sebagian gagal',slow:'Lambat',normal:'Normal'}[kind],rate,ms,total:tests.length,note:`${ok.length}/${tests.length} uji berhasil · ${online.length}/${f.nodes.length} node melapor · 5 menit terakhir`};}
function internetMarkup(f){const q=internetQuality(f);return `<div class="internet-quality"><header><strong>Kualitas internet</strong><span class="badge ${q.kind==='down'?'off':q.kind!=='normal'?'warn':''}"><span class="dot"></span>${q.label}</span></header><div class="internet-details"><span>Keberhasilan <b>${q.rate===null?'—':q.rate.toFixed(1)+'%'}</b></span><span>Respons internet <b>${q.ms===null?'—':q.ms+' ms'}</b></span></div><p>${q.note}</p></div>`;}
function state(f){return f.nodes.some(n=>!n.lastSeen)?'warning':f.nodes.some(n=>!n.online)?'critical':f.nodes.some(n=>n.rssi < -70||n.latency>60||Object.values(n.services||{}).some(s=>['dns_failed','tcp_failed'].includes(s.status)))||internetQuality(f).kind!=='normal'?'warning':'healthy';}
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.remove('hidden');toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),2600);}
function linePaths(history,width,height,max,left=0,top=0,maxGap=35000){let paths=[],points=[],last=null;for(const sample of history){const x=left+(sample.time-(serverNow-300000))/300000*width;if(sample.value===null||(last!==null&&sample.time-last>maxGap)){if(points.length)paths.push(points);points=[];}if(sample.value!==null)points.push(`${x},${top+height-sample.value/max*height}`);last=sample.time;}if(points.length)paths.push(points);return paths;}
function spark(f){if(!f.nodes[0].online||!f.history.some(s=>s.value!==null))return '<div class="sparkline" style="display:grid;place-items:center;color:var(--muted);font-size:11px">Tidak ada pengukuran lokal terbaru</div>';const max=Math.max(100,...f.history.map(s=>s.value??0)),c=colors[(f.id-1)%colors.length];return `<svg class="sparkline" viewBox="0 0 400 58" preserveAspectRatio="none" role="img" aria-label="Tren respons lokal">${linePaths(f.history,400,45,max,0,5,Math.max(35000,(f.nodes[0].details?.delivery?.send_interval_s||10)*1500)).map(points=>`<polyline points="${points.join(' ')}" fill="none" stroke="${c}" stroke-width="1.6" vector-effect="non-scaling-stroke"/>`).join('')}</svg>`;}
const escapeHTML=value=>String(value??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));



function deviceDetails(n){const d=n.details||{},w=d.wifi||{},h=d.device_health||{},p=d.ping,diag=d.diagnostics||{};const field=(label,value,mono=false)=>`<div class="info-row"><dt>${label}</dt><dd class="${mono?'mono':''}">${escapeHTML(value)}</dd></div>`;const age=p?Math.round((p.age_ms+Math.max(0,serverNow-(n.lastSeen||serverNow)))/1000):null;const icon=path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;const wifiIcon=icon('<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r=".8"/>');const chipIcon=icon('<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/><path d="M10 10h4v4h-4z"/>');const pulseIcon=icon('<path d="M2 12h5l3-7 4 14 3-7h5"/>');
return `<section class="device-details">${!Object.keys(d).length?'<div class="metadata-notice">Detail belum tersedia. Perbarui firmware ESP dan backend untuk menerima informasi lengkap.</div>':''}<div class="tech-snapshot"><span class="dot ${n.online?'green-text':'amber-text'}"></span>${historyDate?(n.lastSeen?(historyDate===todayWib()?'Hari ini · ':'Arsip '+historyDate+' · ')+'laporan terakhir '+time(n.lastSeen):'Tidak ada laporan pada tanggal ini'):n.lastSeen?'Data diterima '+time(n.lastSeen)+(n.online?'':' · Snapshot terakhir, perangkat offline'):'Menunggu laporan perangkat'}</div><div class="info-grid"><article class="info-card"><div class="info-card-heading"><span class="info-icon">${wifiIcon}</span><div><h3>Jaringan Wi-Fi</h3><p>Access point dan konfigurasi IP</p></div></div><div class="info-highlight"><span>Terhubung ke</span><strong>${escapeHTML(w.ssid)}</strong><span class="info-channel">Kanal ${escapeHTML(w.channel)}</span></div><dl>${field('IP perangkat',w.ip,true)}${field('Gateway',w.gateway,true)}${field('DNS',w.dns,true)}${field('BSSID',w.bssid,true)}</dl></article><article class="info-card"><div class="info-card-heading"><span class="info-icon">${chipIcon}</span><div><h3>Kesehatan perangkat</h3><p>Kondisi Wemos D1 Mini</p></div></div><div class="info-highlight"><span>Waktu aktif saat laporan</span><strong>${h.uptime_s===undefined?'—':Math.floor(h.uptime_s/3600)+'<small> jam </small>'+Math.floor(h.uptime_s%3600/60)+'<small> menit</small>'}</strong><span class="info-channel">Firmware ${escapeHTML(d.firmware_version)}</span></div><dl>${field('Memori bebas',h.free_heap_bytes===undefined?null:Math.round(h.free_heap_bytes/1024)+' KB')}${field('Fragmentasi memori',h.heap_fragmentation_percent===undefined?null:h.heap_fragmentation_percent+'%')}${field('Alasan restart',h.reset_reason)}</dl></article><article class="info-card"><div class="info-card-heading"><span class="info-icon">${pulseIcon}</span><div><h3>Stabilitas & diagnostik</h3><p>Gangguan sejak perangkat menyala</p></div></div><div class="info-highlight"><span>Wi-Fi terputus</span><strong>${escapeHTML(w.disconnect_count)}<small> kali</small></strong><span class="info-channel">Total ${w.disconnected_ms===undefined?'—':(w.disconnected_ms/1000).toFixed(1)} detik</span></div><dl>${field('HTTP / error lokal',diag.local_http_code,true)}${diag.internet_test_kind==='dns_tcp'?field('Uji internet','DNS + TCP')+field('Tujuan uji terakhir',serviceNames[diag.service_target]||'Tidak diuji pada laporan ini'):field('HTTP / error internet',diag.internet_http_code,true)}${field('Kode putus terakhir',w.last_disconnect_reason===0?'Tidak ada':w.last_disconnect_reason,true)}</dl></article></div><article class="ping-card"><div class="info-card-heading"><span class="info-icon">${pulseIcon}</span><div><h3>Ping manual terakhir</h3><p>${p?escapeHTML(p.target)+' · '+age+' detik lalu':'Belum ada pengujian ping'}</p></div>${p?`<span class="badge ${p.loss_percent?'warn':''}">${p.loss_percent}% loss</span>`:'<span class="badge warn">Belum diuji</span>'}</div>${p?`<div class="ping-metrics"><div><span>Balasan</span><strong>${p.received}<small> / ${p.sent} paket</small></strong></div><div><span>RTT minimum</span><strong>${p.min_ms??'—'}<small> ms</small></strong></div><div><span>RTT rata-rata</span><strong>${p.avg_ms??'—'}<small> ms</small></strong></div><div><span>RTT maksimum</span><strong>${p.max_ms??'—'}<small> ms</small></strong></div></div>`:'<p class="ping-empty-note">Jalankan ping dari tombol Ping pada dashboard utama. Hasilnya akan ditampilkan di sini.</p>'}</article></section>`;}
const serviceNames={google:'Google',youtube:'YouTube',tiktok:'TikTok',netflix:'Netflix'};
