const providerColors={google:'#4285f4',youtube:'#ef4444',tiktok:'#16a6a3',netflix:'#aa478b'};
function drawServiceChart(){if(!selectedDevice||historyDate){drawSummaryChart('internet-chart',true);return;}const metric=$('service-metric').value||'both',metrics=metric==='both'?['dns','tcp']:[metric];const sets=Object.keys(serviceNames).flatMap(name=>metrics.map(seriesMetric=>{const buckets=new Map();for(const f of floors){for(const sample of f.nodes[0].service_history?.[name]||[]){const bucket=selectedDevice?sample.time:Math.floor(sample.time/10000)*10000;if(!buckets.has(bucket))buckets.set(bucket,{time:bucket,values:[],failed:0,dns:[],tcp:[],max_gap_ms:sample.max_gap_ms||Math.max(90000,(f.nodes[0].details?.delivery?.telemetry_interval_s||60)*5000)});const b=buckets.get(bucket),ok=seriesMetric==='dns'?sample.dns_ok:sample.tcp_ok;if(!ok)b.failed++;else{b.values.push(seriesMetric==='dns'?sample.dns_ms:seriesMetric==='tcp'?sample.tcp_ms:sample.dns_ms+sample.tcp_ms);}b.dns.push(sample.dns_ms);if(sample.tcp_ms!==null)b.tcp.push(sample.tcp_ms);}}return{name,metric:seriesMetric,history:[...buckets.values()].sort((a,b)=>a.time-b.time).map(b=>({...b,value:b.values.length?b.values.reduce((a,v)=>a+v,0)/b.values.length:null}))};}));const scale=Math.max(50,Math.ceil(Math.max(0,...sets.flatMap(d=>d.history.map(s=>s.value??0)))/50)*50);let svg='';for(let i=0;i<5;i++){const y=15+i*50;svg+=`<line x1="48" y1="${y}" x2="748" y2="${y}" stroke="var(--chart-grid)"/><text x="0" y="${y+4}" fill="var(--chart-label)" font-size="11">${Math.round(scale*(1-i/4))}</text>`;}for(const {name,history,metric:seriesMetric} of sets){const color=providerColors[name];let points=[],last=null,lastGap=90000;const flush=()=>{if(points.length)svg+=`<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="2.2" stroke-dasharray="${seriesMetric==='tcp'?'6 4':'none'}" stroke-linejoin="round"/>`;points=[];};for(const sample of history){const x=48+(sample.time-(serverNow-300000))/300000*700;const gap=Math.max(lastGap,sample.max_gap_ms||90000);if(last!==null&&sample.time-last>gap)flush();lastGap=sample.max_gap_ms||90000;if(sample.value===null)flush();else{const y=215-sample.value/scale*200;points.push(`${x},${y}`);svg+=`<circle cx="${x}" cy="${y}" r="3" fill="${seriesMetric==='tcp'?'var(--panel)':color}" stroke="${color}" stroke-width="1.8"><title>${serviceNames[name]} · ${time(sample.time)} · ${metricName(seriesMetric)} ${sample.value.toFixed(1)} ms${selectedDevice?'':' · rata-rata '+sample.values.length+' uji'}</title></circle>`;}if(sample.failed)svg+=`<text x="${x+(metric==='both'?(seriesMetric==='tcp'?8:-8):0)}" y="${211-Object.keys(serviceNames).indexOf(name)*13}" text-anchor="middle" fill="${color}" font-size="15"><title>${serviceNames[name]} · ${metricName(seriesMetric)} · ${time(sample.time)} · ${sample.failed} pengujian gagal</title>${metric==='both'?(seriesMetric==='tcp'?'T×':'D×'):'×'}</text>`;last=sample.time;}flush();}for(let i=0;i<6;i++){const t=serverNow-300000+i*60000;svg+=`<text x="${48+i*140}" y="245" text-anchor="${i===0?'start':i===5?'end':'middle'}" fill="var(--chart-label)" font-size="11">${new Date(t).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</text>`;}if(!sets.some(s=>s.history.length)){const oldBackend=floors.some(f=>f.nodes[0].service_history===undefined);const message=oldBackend?'Restart backend: API belum mengirim riwayat layanan':'Menunggu riwayat pengujian empat layanan';svg+=`<text x="400" y="120" text-anchor="middle" fill="var(--chart-label)" font-size="13">${message}</text>`;}$('internet-chart').innerHTML=svg;$('service-legend').innerHTML=serviceLegend(metric,false);}
if($('service-metric'))$('service-metric').addEventListener('change',drawServiceChart);
function drawMonitoringChart(id,internet){if(!selectedDevice||historyDate){drawSummaryChart(id,false);return;}const datasets=floors.map(f=>({f,history:internet?f.nodes[0].internet.map(t=>({time:t.time,value:t.ok?t.ms:null})):(f.nodes[0].gateway_history||[])}));const values=datasets.flatMap(d=>d.history.map(s=>s.value).filter(v=>v!==null));const scale=Math.max(internet?200:50,Math.ceil(Math.max(0,...values)/50)*50);let svg='';for(let i=0;i<5;i++){const y=15+i*50;svg+=`<line x1="48" y1="${y}" x2="748" y2="${y}" stroke="var(--chart-grid)"/><text x="0" y="${y+4}" fill="var(--chart-label)" font-size="11">${Math.round(scale*(1-i/4))}</text>`;}
for(const {f,history} of datasets){if(!f.nodes[0].online)continue;const color=colors[(f.id-1)%colors.length];let segment=[],last=null,lastGap=35000;const flush=()=>{if(segment.length){svg+=`<polyline points="${segment.map(s=>`${48+(s.time-(serverNow-300000))/300000*700},${215-s.value/scale*200}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>`;for(const point of segment)svg+=`<circle cx="${48+(point.time-(serverNow-300000))/300000*700}" cy="${215-point.value/scale*200}" r="2.4" fill="${color}"><title>Ping gateway ${escapeHTML(point.target||'')} · ${time(point.time)} · ${point.value} ms · ${point.loss_percent??0}% packet loss</title></circle>`;}segment=[];};for(const sample of history){const gap=sample.max_gap_ms||Math.max(internet?65000:35000,(f.nodes[0].details?.delivery?.telemetry_interval_s||60)*1500);if(last!==null&&sample.time-last>Math.max(lastGap,gap))flush();lastGap=gap;if(sample.value===null){flush();svg+=`<text x="${48+(sample.time-(serverNow-300000))/300000*700}" y="210" text-anchor="middle" fill="var(--red)" font-size="14"><title>Ping gateway gagal · ${time(sample.time)}</title>×</text>`;}else segment.push(sample);last=sample.time;}flush();}
for(let i=0;i<6;i++){const t=serverNow-300000+i*60000;svg+=`<text x="${48+i*140}" y="245" text-anchor="${i===0?'start':i===5?'end':'middle'}" fill="var(--chart-label)" font-size="11">${new Date(t).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</text>`;}if(!datasets.some(d=>d.f.nodes[0].online&&d.history.length))svg+='<text x="400" y="120" text-anchor="middle" fill="var(--chart-label)" font-size="13">Menunggu hasil ping gateway dari ESP</text>';
$(id).innerHTML=svg;}
