if(deviceRoute){try{selectedDevice=decodeURIComponent(deviceRoute[1]);}catch(_){selectedDevice=deviceRoute[1];}if($('controller-access'))$('controller-access').href='/controllers/'+encodeURIComponent(selectedDevice)+'/';document.body.classList.add('device-view');$('device-live').classList.remove('hidden');$('data-dialog').classList.remove('hidden');document.querySelector('h1').textContent='Perangkat · '+selectedDevice;document.title=selectedDevice+' · WARON IoT';}

function updateInspector(n){if($('controller-access')){const link=$('controller-access');link.href='/controllers/'+encodeURIComponent(n.id)+'/';link.classList.remove('hidden');}const previousLiveUntil=deviceLiveUntil;deviceLiveUntil=n.control?.mode==='live'?Date.now()+n.control.live_remaining_s*1000:0;if(liveViewRequested&&!deviceLiveBusy&&previousLiveUntil>0&&!deviceLiveUntil){liveViewRequested=false;setTimeout(()=>selectDeviceView(todayWib()),0);}updateDeviceLiveButton();const report=n.details?.delivery;$('device-live').title=n.control?.mode==='live'?(report?.mode==='live'?'ESP menjalankan Live. Klik untuk menghentikan.':'Menunggu ESP menerapkan Live. Klik untuk membatalkan.'):'Live perangkat ini setiap 2 detik selama maksimal 2 menit';$('data-title').textContent='Informasi perangkat';$('device-inspector').innerHTML=deviceDetails(n).replace(/<button[^>]*data-device-json[^>]*>.*?<\/button>/,'');$('raw-data').textContent=JSON.stringify({device_id:n.id,received_at_ms:n.lastSeen,online:historyDate?null:n.online,rssi:n.rssi,local_ms:n.latency,internet_ok:n.latestInternetOk,internet_ms:n.latestInternetMs,...n.details},null,2);}
function consumeSnapshot(data){summary24h=data.summary_24h||null;if(selectedDevice&&data.serverTime<serverNow&&apiConnected)return;floors=data.floors.flatMap(f=>f.nodes.map(n=>({...f,floorKey:f.building+'|'+f.id,name:f.name+' · '+n.position,area:f.building,nodes:[n],history:n.history||f.history}))).map((f,i)=>({...f,id:i+1}));if(selectedDevice)floors=floors.filter(f=>f.nodes[0].id===selectedDevice);serverNow=data.serverTime;apiConnected=true;logs=floors.filter(f=>f.nodes[0].lastSeen).map(f=>{const n=f.nodes[0];return{time:n.lastSeen,type:n.online?'ok':'off',title:n.id+(n.online?' · Telemetri diterima':' · Telemetri terputus'),detail:f.name+' · '+internetQuality(f).label};}).sort((a,b)=>b.time-a.time);render();if(selectedDevice){const selected=floors.flatMap(f=>f.nodes).find(n=>n.id===selectedDevice);if(selected){updateInspector(selected);document.querySelector('h1').textContent=selected.name||selected.id;}else{$('device-inspector').textContent='Perangkat tidak ditemukan. Periksa ID di konfigurasi JSON.';}}$('connection').className='badge';$('connection').textContent='Terhubung';$('connection-detail').textContent=floors.length?'Data langsung dari Wemos · Penempatan dari JSON · Batas offline mengikuti interval kirim ESP':'Belum ada perangkat terdaftar. Daftarkan Wemos melalui backend.';$('updated').textContent=`Diterima dari server ${time(serverNow)} · Tampilan mengikuti pengiriman ESP`;if(selectedDevice){const f=floors[0],n=f?.nodes[0];$('breadcrumb-device').textContent=selectedDevice;$('connection-detail').textContent=n?[f.area,'Lantai '+n.floorId,n.position,selectedDevice].filter(Boolean).join(' · '):'Perangkat tidak ditemukan';$('device-state').className='badge '+(n?.online?'':n?.lastSeen?'off':'warn');$('device-state').textContent=n?.online?'● Online':n?.lastSeen?'● Offline':'Menunggu data';$('last-report').textContent=n?.lastSeen?'Laporan terakhir '+time(n.lastSeen):'Belum ada laporan';}else{$('connection').textContent='Ringkasan 24 jam';$('connection-detail').textContent='Ringkasan historis dan kondisi perangkat terakhir';$('updated').textContent='Snapshot '+new Date(serverNow).toLocaleString('id-ID')+' · pembaruan setiap 5 menit';if($('average'))$('average').textContent=summary24h?.local.average_ms??'—';}}
function disconnected(){if(selectedDevice){$('device-state').className='badge warn';$('device-state').textContent='Status belum diketahui';$('last-report').textContent='Menunggu koneksi server';}apiConnected=false;floors=[];logs=[];render();if(selectedDevice){$('device-inspector').textContent='Koneksi server terputus; detail terakhir belum terverifikasi.';$('raw-data').textContent='';}$('connection').className='badge off';$('connection').textContent=historyDate?'RIWAYAT GAGAL DIMUAT':selectedDevice?'MENGHUBUNGKAN ULANG':'RINGKASAN BELUM TERSEDIA';$('connection-detail').textContent=selectedDevice?'Koneksi Live terputus. Mencoba kembali otomatis; status perangkat belum diketahui.':'Ringkasan belum dapat dimuat. Periksa backend dan endpoint /api/overview.';$('updated').textContent=selectedDevice?'Tidak ada koneksi Live ke backend':'Ringkasan gagal dimuat · dicoba kembali pada pembaruan 5 menit';}
async function loadInitialDevices(){
 try{const response=await fetch('/api/devices/status',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(response.ok){consumeSnapshot(await response.json());$('connection').textContent='Memuat ringkasan…';$('updated').textContent='Daftar perangkat tersedia · menghitung ringkasan 24 jam';}}
 catch(_){}finally{refresh();}
}
async function refresh(){const seq=++requestSequence,requestedDate=historyDate;try{const r=await fetch(selectedDevice?'/api/dashboard?device_id='+encodeURIComponent(selectedDevice)+(historyDate?'&date='+encodeURIComponent(historyDate):''):'/api/overview',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const data=await r.json();if(seq!==requestSequence||requestedDate!==historyDate)return;consumeSnapshot(data);if(historyDate){$('connection').textContent=historyDate===todayWib()?'Hari ini · realtime':'Riwayat · '+historyDate;$('device-state').textContent=historyDate===todayWib()?'Data hari ini':'Arsip';$('last-report').textContent=data.samples+' laporan pada tanggal ini';$('updated').textContent=historyDate===todayWib()?'Hari ini · 00.00–24.00 WIB · diperbarui saat data masuk':'Riwayat '+historyDate+' WIB · rata-rata per jam';}}catch(_){if(seq===requestSequence&&requestedDate===historyDate){if(!selectedDevice&&floors.length){$('connection').className='badge warn';$('connection').textContent='Ringkasan belum termuat';$('updated').textContent='Daftar perangkat dari snapshot terakhir · ringkasan gagal dimuat';if(!summary24h&&$('network-insights'))$('network-insights').textContent='Ringkasan belum berhasil dimuat. Daftar perangkat terakhir tetap ditampilkan.';}else disconnected();}}}
function startLive(){if(fallbackTimer)clearInterval(fallbackTimer);if(liveStream)liveStream.close();if(!('EventSource' in window)){$('connection-detail').textContent='Browser tidak mendukung koneksi langsung. Memperbarui otomatis setiap 5 detik.';refresh();fallbackTimer=setInterval(()=>{if(!historyDate||historyDate===todayWib())refresh();},5000);return;}liveStream=new EventSource('/api/events?device_id='+encodeURIComponent(selectedDevice));$('connection').className='badge warn';$('connection').textContent=historyDate?'MENGHUBUNGKAN DATA':'MENGHUBUNGKAN LIVE';const source=liveStream;liveStream.addEventListener('dashboard',event=>{if(source!==liveStream)return;if(historyDate){if(followToday&&historyDate!==todayWib())selectDeviceView(todayWib());else if(historyDate===todayWib())refresh();return;}try{consumeSnapshot(JSON.parse(event.data));}catch(_){disconnected();}});liveStream.onerror=()=>{if(source===liveStream&&(!historyDate||historyDate===todayWib()))disconnected();};}
function updateDeviceLiveButton(){if(liveViewRequested&&!deviceLiveBusy&&deviceLiveUntil>0&&deviceLiveUntil<=Date.now()){deviceLiveUntil=0;liveViewRequested=false;selectDeviceView(todayWib());return;}const seconds=Math.max(0,Math.ceil((deviceLiveUntil-Date.now())/1000)),active=seconds>0;const button=$('device-live');button.textContent=deviceLiveBusy?'Memproses…':active?'■ Live · '+seconds+' dtk':'● Live';button.setAttribute('aria-pressed',String(active));button.classList.toggle('active',active);button.disabled=deviceLiveBusy;}
$('device-live').addEventListener('click',async()=>{if(!selectedDevice||deviceLiveBusy)return;const previousDate=historyDate;const device=selectedDevice,mode=deviceLiveUntil>Date.now()?'telemetry':'live';deviceLiveBusy=true;if(mode==='live')selectDeviceView(null);updateDeviceLiveButton();async function request(){const headers={'Content-Type':'application/json'};if(controlToken)headers.Authorization='Bearer '+controlToken;return fetch('/api/v1/devices/'+encodeURIComponent(device)+'/control',{method:'POST',headers,body:JSON.stringify({mode,live_interval_s:2,live_duration_s:120}),signal:AbortSignal.timeout(5000)});}try{let response=await request();if(response.status===401){const token=window.prompt('Masukkan token API backend untuk mengendalikan perangkat ini:');if(!token)throw Error('Permintaan dibatalkan');controlToken=token.trim();response=await request();}const data=await response.json();if(!response.ok)throw Error(data.error||'Permintaan Live gagal');deviceLiveUntil=data.mode==='live'?Date.now()+data.live_remaining_s*1000:0;liveViewRequested=data.mode==='live';if(data.mode!=='live')selectDeviceView(todayWib());notify(mode==='live'?'Live diminta untuk '+device+' · maksimal 2 menit':'Live '+device+' dihentikan');refresh();}catch(error){notify(error.message);if(mode==='live')selectDeviceView(previousDate||todayWib());}finally{deviceLiveBusy=false;updateDeviceLiveButton();}});
setInterval(updateDeviceLiveButton,1000);
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});render();}));
function clock(){const d=new Date();$('clock').textContent=d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}).replace('.',':');$('date').textContent=d.toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short',year:'numeric'});}clock();setInterval(clock,1000);render();if(!selectedDevice){loadInitialDevices();setInterval(refresh,300000);}

if($('history-date')){
 function selectView(date){
  historyDate=date;followToday=!date||date===todayWib();liveViewRequested=!date;
  requestSequence++;
  if(liveStream){liveStream.close();liveStream=null;}
  if(fallbackTimer){clearInterval(fallbackTimer);fallbackTimer=null;}
  apiConnected=false;summary24h=null;floors=[];render();
  $('device-live').classList.remove('hidden');
  $('history-date').max=todayWib();$('history-date').value=date||todayWib();
  $('view-note').textContent=date?(followToday?'Hari ini · 00.00–24.00 WIB · diperbarui otomatis':'Riwayat '+date+' WIB · 00.00–24.00'):'Live ESP · 5 menit terakhir · maksimal 2 menit';
  document.querySelectorAll('[data-chart-period]').forEach(el=>el.textContent=date?date+' · 24 jam':'Live · 5 menit terakhir');
  refresh();if(!date||followToday)startLive();
 }
 selectDeviceView=selectView;
 $('history-date').addEventListener('change',()=>{const date=$('history-date').value;if(date)selectView(date);});
 $('view-history').addEventListener('click',()=>{const date=$('history-date').value;if(!date){notify('Pilih tanggal dahulu');return;}selectView(date);});
 selectView(todayWib());
 // Refresh the calendar and automatically follow the next day at midnight WIB.
 setInterval(()=>{const today=todayWib();$('history-date').max=today;if(followToday&&historyDate&&historyDate!==today)selectView(today);},30000);
}

// Ping is requested only for the selected device; ordinary overview polling stays unchanged.
if ($('ping-dialog')) {
  let pingDevice='',pingBusy=false,pingPoll=0;
  $('floors').addEventListener('click',event=>{
    const button=event.target.closest('[data-ping-device]');if(!button||pingBusy)return;
    pingDevice=button.dataset.pingDevice;$('ping-device-name').textContent=pingDevice;
    $('remote-ping-result').textContent='Belum ada pengujian.';$('ping-dialog').showModal();
  });
  $('close-ping').addEventListener('click',()=>{$('ping-dialog').close();});
  $('remote-ping-form').addEventListener('submit',async event=>{
    event.preventDefault();if(pingBusy)return;pingBusy=true;$('submit-ping').disabled=true;
    const device=pingDevice,url='/api/v1/devices/'+encodeURIComponent(device)+'/ping';
    const headers=()=>({'Content-Type':'application/json',...(controlToken?{Authorization:'Bearer '+controlToken}:{})});
    try {
      const body=JSON.stringify({target:$('remote-ping-target').value.trim()});
      let response=await fetch(url,{method:'POST',headers:headers(),body,signal:AbortSignal.timeout(5000)});
      if(response.status===401){const token=window.prompt('Token API backend:');if(!token)throw Error('Permintaan dibatalkan');controlToken=token.trim();response=await fetch(url,{method:'POST',headers:headers(),body,signal:AbortSignal.timeout(5000)});}
      const job=await response.json();if(!response.ok)throw Error(job.error||'Tidak dapat meminta ping');
      $('remote-ping-result').textContent='Menunggu '+device+' mengambil perintah…';
      const deadline=Date.now()+65000;
      while(Date.now()<deadline){
        await new Promise(resolve=>{pingPoll=setTimeout(resolve,2000);});
        const r=await fetch(url,{headers:headers(),cache:'no-store',signal:AbortSignal.timeout(5000)});
        const data=await r.json();if(!r.ok)throw Error(data.error||'Gagal membaca hasil');
        if(data.job_id!==job.job_id)throw Error('Permintaan telah diganti');
        if(data.status==='expired')throw Error('Permintaan kedaluwarsa. Periksa koneksi dan firmware ESP.');
        if(data.status==='completed'){
          const p=data.result;
          const packets=p.packets||[];
          const lines=packets.map(packet=>packet.ok?packet.bytes+' bytes from '+p.target+': icmp_seq='+packet.seq+' time='+packet.ms+' ms':'Request timeout for icmp_seq='+packet.seq);
          if(!packets.length)lines.push('Detail per paket belum tersedia. Perbarui firmware ESP ke v1.11.0.');
          lines.push('', '--- '+p.target+' ping statistics ---',p.sent+' packets transmitted, '+p.received+' packets received, '+p.loss_percent+'% packet loss');
          if(p.received)lines.push('round-trip min/avg/max = '+p.min_ms+'/'+p.avg_ms+'/'+p.max_ms+' ms');
          lines.push('', 'Sumber: '+device+' · TTL tidak tersedia dari SDK ESP8266 · waktu resolusi 1 ms');
          $('remote-ping-result').textContent=lines.join('\n');
          return;
        }
      }
      throw Error('Batas tunggu habis. Periksa firmware ESP.');
    } catch(error){$('remote-ping-result').textContent=error.message;}
    finally{pingBusy=false;$('submit-ping').disabled=false;}
  });
}
